"use client";

import { useEffect, useCallback, useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { useAuth } from "@/hooks/useAuth";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { useAuthPageConfig } from "@/hooks/useAuthPageConfig";
import { AuthLayout } from "@/components/auth/AuthLayout";
import { AuthLeftPanel } from "@/components/auth/AuthLeftPanel";
import { SignInForm } from "@/components/auth/SignInForm";
import { SignUpForm } from "@/components/auth/SignUpForm";
import { ForgotPasswordForm } from "@/components/auth/ForgotPasswordForm";

type AuthView = "signin" | "signup" | "forgot-password";

const Auth = () => {
  const { user, loading } = useAuth();
  const { config } = useAuthPageConfig();
  const router = useRouter();
  const searchParams = useSearchParams();
  const inviteToken = searchParams?.get("invite") ?? null;
  const tabParam = searchParams?.get("tab");

  // Open-redirect protection: only allow same-origin paths starting with
  // a single "/" (not "//" or "/\" which can become protocol-relative).
  const rawNext = searchParams?.get("next") ?? "/";
  const nextPath = /^\/(?![/\\])/.test(rawNext) ? rawNext : "/";

  const [view, setView] = useState<AuthView>(
    tabParam === "signup" ? "signup" : "signin",
  );

  // ── Team invite handler ────────────────────────────────────────────
  const acceptInvite = useCallback(
    async (token: string) => {
      try {
        const {
          data: { session },
        } = await supabase.auth.getSession();
        if (!session?.access_token) return;

        const res = await fetch(
          `${process.env.NEXT_PUBLIC_SUPABASE_URL}/functions/v1/accept-team-invite`,
          {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              Authorization: `Bearer ${session.access_token}`,
              apikey: process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY ?? "",
            },
            body: JSON.stringify({ token }),
          },
        );

        const json = await res.json();
        if (res.ok && json.success) {
          toast.success(`Joined team: ${json.team_name ?? "Team"}`);
          router.replace("/team");
          return;
        }
      } catch {
        // Silently fail — user can accept invite manually later
      }
      router.replace(nextPath);
    },
    [router, nextPath],
  );

  // ── Redirect authenticated users ──────────────────────────────────
  useEffect(() => {
    if (!loading && user) {
      if (inviteToken) {
        acceptInvite(inviteToken);
      } else {
        router.replace(nextPath);
      }
    }
  }, [user, loading, router, inviteToken, acceptInvite, nextPath]);

  // ── Auth success callback ─────────────────────────────────────────
  const handleSuccess = useCallback(() => {
    if (inviteToken) {
      acceptInvite(inviteToken);
    } else {
      router.replace(nextPath);
    }
  }, [inviteToken, acceptInvite, router, nextPath]);

  // ── Determine left panel variant ──────────────────────────────────
  const leftVariant = view === "signup" ? "signup" : "signin";

  return (
    <AuthLayout
      left={<AuthLeftPanel config={config} variant={leftVariant} />}
      right={
        <>
          {view === "signin" && (
            <SignInForm
              config={config}
              onSuccess={handleSuccess}
              onSwitchToSignUp={() => setView("signup")}
              onForgotPassword={() => setView("forgot-password")}
            />
          )}
          {view === "signup" && (
            <SignUpForm
              config={config}
              onSuccess={handleSuccess}
              onSwitchToSignIn={() => setView("signin")}
            />
          )}
          {view === "forgot-password" && (
            <ForgotPasswordForm onBack={() => setView("signin")} />
          )}
        </>
      }
    />
  );
};

export default Auth;

