"use client";

import { Lock, Shield, CheckCircle } from "lucide-react";
import type { TrustBadge } from "@/hooks/useAuthPageConfig";

const ICON_MAP = {
  lock: Lock,
  shield: Shield,
  "check-circle": CheckCircle,
} as const;

export function TrustBadges({ badges }: { badges: TrustBadge[] }) {
  if (badges.length === 0) return null;

  return (
    <div className="flex items-center justify-center gap-5 border-t border-border pt-5" role="list" aria-label="Trust certifications">
      {badges.map((badge, i) => {
        const Icon = ICON_MAP[badge.icon] ?? CheckCircle;
        return (
          <div key={i} role="listitem" className="flex items-center gap-1.5 text-xs text-muted-foreground/70">
            <Icon aria-hidden="true" className="h-3.5 w-3.5" />
            {badge.label}
          </div>
        );
      })}
    </div>
  );
}

