"use client";

import { useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import { Loader2 } from "lucide-react";
import type { AuthPageConfig } from "@/hooks/useAuthPageConfig";
import { SocialAuthButtons } from "./SocialAuthButtons";
import { Divider } from "./Divider";
import { TrustBadges } from "./TrustBadges";

interface SignInFormProps {
  config: AuthPageConfig;
  onSuccess?: () => void;
  onSwitchToSignUp: () => void;
  onForgotPassword: () => void;
}

export function SignInForm({
  config,
  onSuccess,
  onSwitchToSignUp,
  onForgotPassword,
}: SignInFormProps) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const { error } = await supabase.auth.signInWithPassword({
        email,
        password,
      });
      if (error) {
        toast.error(error.message);
      } else {
        toast.success("Signed in successfully");
        onSuccess?.();
      }
    } catch {
      toast.error("An unexpected error occurred. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const hasSso = config.google_auth_enabled || config.microsoft_auth_enabled;

  return (
    <div className="flex w-full flex-col justify-center bg-background px-6 py-10 sm:px-10 lg:px-14">
      <div className="mx-auto w-full max-w-[400px]">
        {/* Mobile logo — visible only below md */}
        <div className="mb-8 flex items-center gap-2.5 md:hidden">
          <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-gradient-to-br from-auth-accent to-auth-accent/80 text-sm font-extrabold text-white">
            R
          </div>
          <span className="text-xl font-bold tracking-tight text-foreground">
            Rankora
          </span>
        </div>

        {/* Header */}
        <div className="mb-7">
          <h1 className="text-2xl font-bold tracking-tight text-foreground sm:text-3xl">
            {config.signin_heading}
          </h1>
          <p className="mt-1.5 text-sm text-muted-foreground">
            {config.signin_subheading}
          </p>
        </div>

        {/* SSO */}
        <SocialAuthButtons
          googleEnabled={config.google_auth_enabled}
          microsoftEnabled={config.microsoft_auth_enabled}
          mode="signin"
          disabled={loading}
        />

        {hasSso && (
          <div className="my-5">
            <Divider />
          </div>
        )}

        {/* Email / Password form */}
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-1.5">
            <label
              htmlFor="signin-email"
              className="text-sm font-medium text-foreground"
            >
              Email
            </label>
            <Input
              id="signin-email"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="name@company.com"
              autoComplete="email"
              required
              disabled={loading}
              className="h-11 rounded-lg"
            />
          </div>

          <div className="space-y-1.5">
            <label
              htmlFor="signin-password"
              className="text-sm font-medium text-foreground"
            >
              Password
            </label>
            <Input
              id="signin-password"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="Enter your password"
              autoComplete="current-password"
              required
              disabled={loading}
              className="h-11 rounded-lg"
            />
          </div>

          {/* Remember me + Forgot */}
          <div className="flex items-center justify-between">
            <label className="flex cursor-pointer items-center gap-2 text-sm text-muted-foreground">
              <input
                type="checkbox"
                defaultChecked
                className="h-4 w-4 rounded border-border accent-auth-accent"
              />
              Remember me
            </label>
            <button
              type="button"
              onClick={onForgotPassword}
              className="text-sm font-medium text-auth-accent hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 rounded-sm"
            >
              Forgot password?
            </button>
          </div>

          {/* Submit */}
          <button
            type="submit"
            disabled={loading}
            className="relative mt-2 flex w-full items-center justify-center rounded-lg bg-auth-btn px-4 py-3 text-sm font-semibold text-white transition-all hover:-translate-y-px hover:bg-auth-btn-hover hover:shadow-lg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 active:translate-y-0 disabled:pointer-events-none disabled:opacity-50"
          >
            {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            Sign in
          </button>
        </form>

        {/* Switch to signup */}
        <p className="mt-5 text-center text-sm text-muted-foreground">
          Don&apos;t have an account?{" "}
          <button
            type="button"
            onClick={onSwitchToSignUp}
            className="font-semibold text-auth-accent hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 rounded-sm"
          >
            Start free trial &rarr;
          </button>
        </p>

        {/* Trust badges */}
        <div className="mt-6">
          <TrustBadges badges={config.trust_badges} />
        </div>
      </div>
    </div>
  );
}

