"use client";

import { useEffect } from "react";
import { useRouter } from "next/navigation";
import { useAuth } from "@/hooks/useAuth";

/**
 * Layout-preserving skeleton that matches the sidebar+content structure.
 * Prevents width/layout shift while auth state is loading.
 */
const AuthLoader = () => (
  <div className="flex h-svh w-full overflow-hidden">
    <div className="hidden md:flex w-[var(--sidebar-width,16rem)] shrink-0 flex-col border-r border-border bg-sidebar">
      <div className="px-4 py-4">
        <div className="h-5 w-24 rounded bg-muted animate-pulse" />
      </div>
      <div className="border-t border-border" />
      <div className="p-3 space-y-2">
        {[1, 2, 3, 4].map((i) => (
          <div key={i} className="h-8 rounded-md bg-muted/50 animate-pulse" />
        ))}
      </div>
    </div>
    <div className="flex-1 flex flex-col min-w-0">
      <div className="h-14 border-b border-border flex items-center justify-between px-4 shrink-0">
        <div className="h-4 w-20 rounded bg-muted animate-pulse" />
        <div className="flex items-center gap-3">
          <div className="h-8 w-8 rounded-lg bg-muted animate-pulse" />
          <div className="h-8 w-8 rounded-full bg-muted animate-pulse" />
        </div>
      </div>
      <div className="flex-1 overflow-y-auto p-6">
        <div className="max-w-5xl mx-auto space-y-4">
          <div className="h-7 w-48 rounded bg-muted animate-pulse" />
          <div className="h-4 w-72 rounded bg-muted/60 animate-pulse" />
        </div>
      </div>
    </div>
  </div>
);

/**
 * Client-side protected route guard. Second line of defense — the Next.js
 * proxy (proxy.ts) is the primary gate and redirects before this runs.
 * Used inside protected route group layouts for UX (avoids flash during
 * initial client-side auth hydration).
 */
export const ProtectedRoute = ({ children }: { children: React.ReactNode }) => {
  const { user, loading } = useAuth();
  const router = useRouter();

  useEffect(() => {
    if (!loading && !user) router.replace("/auth");
  }, [loading, user, router]);

  if (loading || !user) return <AuthLoader />;
  return <>{children}</>;
};

export const AdminRoute = ({ children }: { children: React.ReactNode }) => {
  const { user, loading, isAdmin } = useAuth();
  const router = useRouter();

  useEffect(() => {
    if (loading) return;
    if (!user) router.replace("/auth");
    else if (!isAdmin) router.replace("/");
  }, [loading, user, isAdmin, router]);

  if (loading || !user || !isAdmin) return <AuthLoader />;
  return <>{children}</>;
};

