import { requireUser } from "../_lib/server-auth";
import SidebarLayout from "@/components/SidebarLayout";

/**
 * Shared layout for all authenticated routes. Keeps the sidebar and
 * header mounted across navigations so page switches feel instant
 * (SPA-like). Only the page content inside <SidebarLayout> swaps.
 *
 * Server-side auth gate: requireUser() redirects to /auth if no session.
 * This replaces the per-page requireUser() calls.
 */
export default async function AppLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  await requireUser();
  return <SidebarLayout>{children}</SidebarLayout>;
}

