"use client";

import {
  Briefcase,
  Home,
  Settings,
  CreditCard,
  Users,
  CheckSquare,
  Globe,
  Layers,
  Megaphone,
  FileText,
  Plug,
  BarChart3,
  Building2,
  Bookmark,
  Mail,
} from "lucide-react";
import {
  Sidebar,
  SidebarContent,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuItem,
  SidebarMenuButton,
  SidebarSeparator,
} from "@/components/ui/sidebar";
import { useRouter, usePathname } from "next/navigation";
import Link from "next/link";
import { usePlatformConfig } from "@/hooks/usePlatformConfig";
import { cn } from "@/lib/utils";

interface JobSidebarProps {
  showDashboard?: boolean;
  showMyJobs?: boolean;
  onNewJob?: () => void;
  onDashboard?: () => void;
  onMyJobs?: () => void;
  onAuthRequired?: () => void;
  isAuthenticated?: boolean;
  selectedJobId?: string | null;
}

interface NavItem {
  icon: React.ComponentType<{ className?: string }>;
  label: string;
  isActive: boolean;
  onClick: (() => void) | undefined;
  show?: boolean;
}

const NavItemRow = ({ icon: Icon, label, isActive, onClick }: NavItem) => (
  <SidebarMenuItem>
    <SidebarMenuButton
      isActive={isActive}
      onClick={onClick}
      tooltip={label}
      className={cn(
        "h-8 gap-2.5 rounded-md text-[13px] font-medium transition-colors duration-100",
        isActive
          ? "bg-sidebar-accent text-sidebar-accent-foreground font-semibold"
          : "text-muted-foreground hover:text-foreground hover:bg-sidebar-accent/60"
      )}
    >
      <Icon className={cn("h-4 w-4 shrink-0", isActive ? "text-foreground" : "text-muted-foreground")} />
      <span>{label}</span>
    </SidebarMenuButton>
  </SidebarMenuItem>
);

const SectionLabel = ({ children }: { children: string }) => (
  <p className="px-2 pt-5 pb-1.5 text-[10.5px] font-semibold uppercase tracking-[0.08em] text-muted-foreground/50 select-none group-data-[collapsible=icon]:hidden">
    {children}
  </p>
);

const JobSidebar = ({
  showDashboard,
  showMyJobs,
  onDashboard,
  onMyJobs,
  isAuthenticated = true,
}: JobSidebarProps) => {
  const router = useRouter();
  const pathname = usePathname() ?? "/";
  const { data: config } = usePlatformConfig();
  const appName = config?.app_name || "Rankora";
  const appLogo = config?.app_logo_url || null;

  const mainNav: NavItem[] = [
    { icon: Home, label: "Dashboard", isActive: !!showDashboard, onClick: onDashboard, show: isAuthenticated && !!onDashboard },
    { icon: Briefcase, label: "My Jobs", isActive: !!showMyJobs, onClick: onMyJobs, show: isAuthenticated && !!onMyJobs },
    { icon: Bookmark, label: "Talent Pool", isActive: pathname === "/talent-pool", onClick: () => router.push("/talent-pool"), show: isAuthenticated },
    { icon: CheckSquare, label: "Tasks", isActive: pathname === "/tasks", onClick: () => router.push("/tasks"), show: isAuthenticated },
    { icon: Mail, label: "Sequences", isActive: pathname === "/sequences", onClick: () => router.push("/sequences"), show: isAuthenticated },
    { icon: BarChart3, label: "Reports", isActive: pathname === "/reports", onClick: () => router.push("/reports"), show: isAuthenticated },
  ];

  const orgNav: NavItem[] = [
    { icon: Users, label: "Team Hub", isActive: pathname === "/team", onClick: () => router.push("/team") },
    { icon: Building2, label: "Agency Hub", isActive: pathname === "/agency", onClick: () => router.push("/agency") },
    { icon: Globe, label: "Career Page", isActive: pathname === "/career-settings", onClick: () => router.push("/career-settings") },
    { icon: Plug, label: "Integrations", isActive: pathname === "/integrations", onClick: () => router.push("/integrations") },
    { icon: CreditCard, label: "Billing", isActive: pathname === "/billing", onClick: () => router.push("/billing") },
    { icon: Settings, label: "Settings", isActive: pathname === "/settings", onClick: () => router.push("/settings") },
  ];

  return (
    <Sidebar collapsible="icon" className="border-r-0">
      {/* Brand */}
      <SidebarHeader className="!flex-col !gap-0 !p-0 px-2 pt-4 pb-2 group-data-[collapsible=icon]:px-1 group-data-[collapsible=icon]:items-center">
        <div className="flex items-center gap-2 px-2">
          {appLogo ? (
            <img src={appLogo} alt={appName} className="h-5 w-5 shrink-0 object-contain group-data-[collapsible=icon]:h-6 group-data-[collapsible=icon]:w-6" />
          ) : (
            <Layers className="h-4 w-4 text-primary shrink-0" />
          )}
          <span className="font-bold text-foreground tracking-tight text-base group-data-[collapsible=icon]:hidden">{appName}</span>
        </div>
      </SidebarHeader>

      {/* Navigation */}
      <SidebarContent className="px-2 py-1 group-data-[collapsible=icon]:px-1">
        <SectionLabel>Main</SectionLabel>
        <SidebarMenu>
          {mainNav.filter((i) => i.show !== false).map((item) => <NavItemRow key={item.label} {...item} />)}
        </SidebarMenu>

        {isAuthenticated && (
          <>
            <SectionLabel>Organization</SectionLabel>
            <SidebarMenu>
              {orgNav.map((item) => <NavItemRow key={item.label} {...item} />)}
            </SidebarMenu>
          </>
        )}

        <SectionLabel>Support</SectionLabel>
        <SidebarMenu>
          <SidebarMenuItem>
            <Link href="/request-feature" className={cn("flex items-center gap-2.5 px-2 h-8 rounded-md text-[13px] font-medium transition-colors duration-100 w-full group-data-[collapsible=icon]:justify-center group-data-[collapsible=icon]:px-0", pathname === "/request-feature" ? "bg-sidebar-accent text-sidebar-accent-foreground font-semibold" : "text-muted-foreground hover:text-foreground hover:bg-sidebar-accent/60")}>
              <Megaphone className="h-[15px] w-[15px] shrink-0 text-muted-foreground" />
              <span className="group-data-[collapsible=icon]:hidden">Feature Request</span>
            </Link>
          </SidebarMenuItem>
          <SidebarMenuItem>
            <Link href="/changelog" className={cn("flex items-center gap-2.5 px-2 h-8 rounded-md text-[13px] font-medium transition-colors duration-100 w-full group-data-[collapsible=icon]:justify-center group-data-[collapsible=icon]:px-0", pathname === "/changelog" ? "bg-sidebar-accent text-sidebar-accent-foreground font-semibold" : "text-muted-foreground hover:text-foreground hover:bg-sidebar-accent/60")}>
              <FileText className="h-[15px] w-[15px] shrink-0 text-muted-foreground" />
              <span className="group-data-[collapsible=icon]:hidden">Changelog</span>
            </Link>
          </SidebarMenuItem>
        </SidebarMenu>
      </SidebarContent>
    </Sidebar>
  );
};

export default JobSidebar;

