  icon: React.ComponentType<{ className?: string }>;
  label: string;
  href: string;
  show?: boolean;
}

interface NavCallbackItem {
  icon: React.ComponentType<{ className?: string }>;
  label: string;
  onClick: () => void;
  isActive: boolean;
  show?: boolean;
}

const NavLink = ({ icon: Icon, label, href }: NavLinkItem & { pathname: string }) => {
  // intentionally unused — we receive pathname from the parent
  return null;
};

const SectionLabel = ({ children }: { children: string }) => (
  <p className="px-2 pt-5 pb-1.5 text-[10.5px] font-semibold uppercase tracking-[0.08em] text-muted-foreground/50 select-none group-data-[collapsible=icon]:hidden">
