"use client";

import { useState, lazy, Suspense } from "react";
import AppHeader from "@/components/AppHeader";
import AdminSidebar, { type AdminSection } from "@/components/admin/AdminSidebar";
import AdminErrorBoundary from "@/components/admin/AdminErrorBoundary";

// Lazy-load every admin tab so Recharts, heavy grids, and editor
// components only ship when the user actually opens that tab.
// Dashboard in particular pulls in Recharts (~40KB gzipped).
const DashboardTab = lazy(() => import("@/components/admin/DashboardTab"));
const UsersTab = lazy(() => import("@/components/admin/UsersTab"));
const BillingTab = lazy(() => import("@/components/admin/BillingTab"));
const PlatformSettingsTab = lazy(
  () => import("@/components/admin/PlatformSettingsTab"),
);
const EmailSettingsTab = lazy(
  () => import("@/components/admin/EmailSettingsTab"),
);
const AIPromptsTab = lazy(() => import("@/components/admin/AIPromptsTab"));
const IntegrationsTab = lazy(
  () => import("@/components/admin/IntegrationsTab"),
);
const UsageLogsTab = lazy(() => import("@/components/admin/UsageLogsTab"));
const AuditLogsTab = lazy(() => import("@/components/admin/AuditLogsTab"));
const SystemErrorLogsTab = lazy(
  () => import("@/components/admin/SystemErrorLogsTab"),
);
const SeoTab = lazy(() => import("@/components/admin/SeoTab"));
const ChangelogTab = lazy(() => import("@/components/admin/ChangelogTab"));

const sectionComponents: Record<AdminSection, React.ComponentType> = {
  dashboard: DashboardTab,
  users: UsersTab,
  billing: BillingTab,
  platform_settings: PlatformSettingsTab,
  email_settings: EmailSettingsTab,
  ai_prompts: AIPromptsTab,
  seo: SeoTab,
  changelog: ChangelogTab,

  changelog: ChangelogTab,
  integrations: IntegrationsTab,
  logs: UsageLogsTab,
  audit_logs: AuditLogsTab,
  system_errors: SystemErrorLogsTab,
};

const TabSkeleton = () => (
  <div className="space-y-4">
    <div className="h-7 w-48 rounded bg-muted animate-pulse" />
    <div className="h-4 w-72 rounded bg-muted/60 animate-pulse" />
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 mt-6">
      {[1, 2, 3, 4, 5, 6].map((i) => (
        <div
          key={i}
