-- ============================================================================
-- 20260420000004_bubs_grants.sql
-- ----------------------------------------------------------------------------
-- Grant table-level permissions so PostgREST (Supabase's REST API)
-- can actually return rows to anon and authenticated roles.
--
-- Supabase RLS policies only *filter* rows — they don't grant the
-- underlying SELECT permission. Every public-facing table needs
-- both a GRANT and at least one policy.
--
-- Without this file, every REST call returns "permission denied".
-- ============================================================================

-- ── World-readable tables (public pricing, app catalog, changelog) ─────────
GRANT SELECT ON apps                        TO anon, authenticated;
GRANT SELECT ON plans                       TO anon, authenticated;
GRANT SELECT ON rankora_changelog           TO anon, authenticated;
GRANT SELECT ON rankora_feature_requests    TO anon, authenticated;
GRANT SELECT ON rankora_career_pages        TO anon, authenticated;  -- published only via RLS
GRANT SELECT ON rankora_feature_flags       TO anon, authenticated;  -- global defaults only via RLS

-- Logged-in users can create feature requests + vote
GRANT INSERT, UPDATE ON rankora_feature_requests TO authenticated;
GRANT SELECT, INSERT, DELETE ON rankora_feature_request_votes TO authenticated;

-- ── Authenticated-only tables (account-scoped via RLS) ─────────────────────
-- Every account-scoped table needs SELECT/INSERT/UPDATE/DELETE for
-- authenticated role. RLS policies then filter by account membership.

GRANT SELECT, INSERT, UPDATE, DELETE ON users                        TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON accounts                     TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON account_users                TO authenticated;
GRANT SELECT                          ON account_app_access          TO authenticated;
GRANT SELECT                          ON subscriptions               TO authenticated;
GRANT SELECT                          ON usage_logs                  TO authenticated;
GRANT SELECT                          ON audit_logs                  TO authenticated;

GRANT SELECT, INSERT, UPDATE, DELETE ON rankora_jobs                 TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON rankora_resumes              TO authenticated;
GRANT SELECT,         UPDATE         ON rankora_results              TO authenticated;
GRANT SELECT,         UPDATE         ON rankora_applications         TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON rankora_career_pages         TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON rankora_tasks                TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON rankora_candidate_notes      TO authenticated;
GRANT SELECT, INSERT,         DELETE ON rankora_candidate_tags       TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON rankora_pipeline_stages      TO authenticated;
GRANT SELECT,         UPDATE         ON rankora_platform_config      TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON rankora_api_keys             TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON rankora_feature_flags        TO authenticated;

-- ── Service role: full access (bypasses RLS entirely) ─────────────────────
-- Edge functions running with SUPABASE_SERVICE_ROLE_KEY bypass RLS
-- by default, but we still grant table access explicitly for clarity.
GRANT ALL ON ALL TABLES IN SCHEMA public TO service_role;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO service_role;
GRANT ALL ON ALL FUNCTIONS IN SCHEMA public TO service_role;

-- Ensure future tables (from later migrations) automatically inherit
-- sensible defaults without needing to re-run GRANT for each new table
ALTER DEFAULT PRIVILEGES IN SCHEMA public
