-- ============================================================================
-- 20260420000013_missing_tables_views_rpcs.sql
-- Create ALL missing tables, views, and RPCs the frontend queries.
-- ============================================================================


-- ────────────────────────────────────────────────────────────────────────────
-- PART 1: Missing tables (features added after BUBS migration)
-- ────────────────────────────────────────────────────────────────────────────

-- candidate_stages (pipeline tracking per candidate per job)
CREATE TABLE IF NOT EXISTS candidate_stages (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  resume_id uuid REFERENCES rankora_resumes(id) ON DELETE CASCADE,
  job_id uuid REFERENCES rankora_jobs(id) ON DELETE CASCADE,
  stage text NOT NULL DEFAULT 'new',
  moved_at timestamptz NOT NULL DEFAULT now(),
  moved_by uuid REFERENCES users(id),
  notes text,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_candidate_stages_resume ON candidate_stages(resume_id);
CREATE INDEX IF NOT EXISTS idx_candidate_stages_job ON candidate_stages(job_id);
ALTER TABLE candidate_stages ENABLE ROW LEVEL SECURITY;
CREATE POLICY candidate_stages_all ON candidate_stages FOR ALL TO authenticated USING (true) WITH CHECK (true);
GRANT SELECT, INSERT, UPDATE, DELETE ON candidate_stages TO authenticated;

-- career_subscribers (email subscribers on career pages)
CREATE TABLE IF NOT EXISTS career_subscribers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  career_page_id uuid REFERENCES rankora_career_pages(id) ON DELETE CASCADE,
  email text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(career_page_id, email)
);
ALTER TABLE career_subscribers ENABLE ROW LEVEL SECURITY;
CREATE POLICY career_subscribers_all ON career_subscribers FOR ALL USING (true) WITH CHECK (true);
GRANT SELECT, INSERT, DELETE ON career_subscribers TO authenticated, anon;

-- notifications
CREATE TABLE IF NOT EXISTS notifications (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  title text NOT NULL,
  body text,
  type text DEFAULT 'info',
  read boolean NOT NULL DEFAULT false,
  link text,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id, read, created_at DESC);
ALTER TABLE notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY notifications_select ON notifications FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE POLICY notifications_update ON notifications FOR UPDATE TO authenticated USING (user_id = auth.uid());
CREATE POLICY notifications_delete ON notifications FOR DELETE TO authenticated USING (user_id = auth.uid());
GRANT SELECT, UPDATE, DELETE ON notifications TO authenticated;

-- talent_pool
CREATE TABLE IF NOT EXISTS talent_pool (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id uuid NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  resume_id uuid REFERENCES rankora_resumes(id) ON DELETE SET NULL,
  candidate_name text,
  candidate_email text,
  tags text[],
  notes text,
  source text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE talent_pool ENABLE ROW LEVEL SECURITY;
CREATE POLICY talent_pool_all ON talent_pool FOR ALL TO authenticated USING (is_account_member(account_id)) WITH CHECK (is_account_member(account_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON talent_pool TO authenticated;

-- sequences (email/outreach sequences)
CREATE TABLE IF NOT EXISTS sequences (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id uuid NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  name text NOT NULL,
  description text,
  status text NOT NULL DEFAULT 'draft',
  created_by uuid REFERENCES users(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE sequences ENABLE ROW LEVEL SECURITY;
CREATE POLICY sequences_all ON sequences FOR ALL TO authenticated USING (is_account_member(account_id)) WITH CHECK (is_account_member(account_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON sequences TO authenticated;

-- sequence_steps
CREATE TABLE IF NOT EXISTS sequence_steps (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  sequence_id uuid NOT NULL REFERENCES sequences(id) ON DELETE CASCADE,
  step_order int NOT NULL DEFAULT 1,
  subject text,
  body text,
  delay_days int NOT NULL DEFAULT 1,
  channel text NOT NULL DEFAULT 'email',
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE sequence_steps ENABLE ROW LEVEL SECURITY;
CREATE POLICY sequence_steps_all ON sequence_steps FOR ALL TO authenticated USING (true) WITH CHECK (true);
GRANT SELECT, INSERT, UPDATE, DELETE ON sequence_steps TO authenticated;

-- sequence_enrollments
CREATE TABLE IF NOT EXISTS sequence_enrollments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  sequence_id uuid NOT NULL REFERENCES sequences(id) ON DELETE CASCADE,
  resume_id uuid REFERENCES rankora_resumes(id) ON DELETE SET NULL,
  candidate_email text NOT NULL,
  candidate_name text,
  status text NOT NULL DEFAULT 'active',
  current_step int NOT NULL DEFAULT 1,
  enrolled_at timestamptz NOT NULL DEFAULT now(),
  completed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE sequence_enrollments ENABLE ROW LEVEL SECURITY;
CREATE POLICY sequence_enrollments_all ON sequence_enrollments FOR ALL TO authenticated USING (true) WITH CHECK (true);
GRANT SELECT, INSERT, UPDATE, DELETE ON sequence_enrollments TO authenticated;

-- outreach_log
CREATE TABLE IF NOT EXISTS outreach_log (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  enrollment_id uuid REFERENCES sequence_enrollments(id) ON DELETE CASCADE,
  step_id uuid REFERENCES sequence_steps(id) ON DELETE SET NULL,
  channel text NOT NULL DEFAULT 'email',
  status text NOT NULL DEFAULT 'sent',
  sent_at timestamptz NOT NULL DEFAULT now(),
  opened_at timestamptz,
  clicked_at timestamptz,
  replied_at timestamptz,
  error text
);
ALTER TABLE outreach_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY outreach_log_all ON outreach_log FOR ALL TO authenticated USING (true) WITH CHECK (true);
GRANT SELECT, INSERT, UPDATE ON outreach_log TO authenticated;

-- sms_logs
CREATE TABLE IF NOT EXISTS sms_logs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid REFERENCES users(id),
  to_number text NOT NULL,
  body text NOT NULL,
  status text NOT NULL DEFAULT 'sent',
  provider_id text,
  error text,
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE sms_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY sms_logs_select ON sms_logs FOR SELECT TO authenticated USING (user_id = auth.uid());
GRANT SELECT, INSERT ON sms_logs TO authenticated;

-- interviews
CREATE TABLE IF NOT EXISTS interviews (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  job_id uuid REFERENCES rankora_jobs(id) ON DELETE CASCADE,
  resume_id uuid REFERENCES rankora_resumes(id) ON DELETE CASCADE,
  interviewer_id uuid REFERENCES users(id),
  scheduled_at timestamptz,
  duration_minutes int DEFAULT 60,
  type text DEFAULT 'video',
  status text DEFAULT 'scheduled',
  notes text,
  location text,
  meeting_link text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE interviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY interviews_all ON interviews FOR ALL TO authenticated USING (true) WITH CHECK (true);
GRANT SELECT, INSERT, UPDATE, DELETE ON interviews TO authenticated;

-- availability_slots
CREATE TABLE IF NOT EXISTS availability_slots (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  day_of_week int NOT NULL CHECK (day_of_week BETWEEN 0 AND 6),
  start_time time NOT NULL,
  end_time time NOT NULL,
  timezone text NOT NULL DEFAULT 'UTC',
  is_active boolean NOT NULL DEFAULT true
);
ALTER TABLE availability_slots ENABLE ROW LEVEL SECURITY;
CREATE POLICY availability_slots_own ON availability_slots FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
GRANT SELECT, INSERT, UPDATE, DELETE ON availability_slots TO authenticated;

-- booking_tokens
CREATE TABLE IF NOT EXISTS booking_tokens (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  resume_id uuid REFERENCES rankora_resumes(id),
  job_id uuid REFERENCES rankora_jobs(id),
  token text UNIQUE NOT NULL DEFAULT encode(gen_random_bytes(32), 'hex'),
  expires_at timestamptz NOT NULL DEFAULT (now() + interval '7 days'),
  used_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE booking_tokens ENABLE ROW LEVEL SECURITY;
CREATE POLICY booking_tokens_select ON booking_tokens FOR SELECT USING (true);
CREATE POLICY booking_tokens_insert ON booking_tokens FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid());
GRANT SELECT ON booking_tokens TO anon, authenticated;
GRANT INSERT, UPDATE ON booking_tokens TO authenticated;

-- guest_links
CREATE TABLE IF NOT EXISTS guest_links (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  job_id uuid NOT NULL REFERENCES rankora_jobs(id) ON DELETE CASCADE,
  token text UNIQUE NOT NULL DEFAULT encode(gen_random_bytes(32), 'hex'),
  created_by uuid REFERENCES users(id),
  expires_at timestamptz,
  permissions text[] DEFAULT ARRAY['view'],
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE guest_links ENABLE ROW LEVEL SECURITY;
CREATE POLICY guest_links_all ON guest_links FOR ALL TO authenticated USING (true) WITH CHECK (true);
CREATE POLICY guest_links_public ON guest_links FOR SELECT USING (true);
GRANT SELECT ON guest_links TO anon, authenticated;
GRANT INSERT, UPDATE, DELETE ON guest_links TO authenticated;

-- hire_outcomes
CREATE TABLE IF NOT EXISTS hire_outcomes (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  job_id uuid REFERENCES rankora_jobs(id) ON DELETE CASCADE,
  resume_id uuid REFERENCES rankora_resumes(id) ON DELETE CASCADE,
  outcome text NOT NULL DEFAULT 'hired',
