GRANT SELECT, INSERT ON system_error_logs TO authenticated;


-- ────────────────────────────────────────────────────────────────────────────
-- PART 2: Analytics views
-- ────────────────────────────────────────────────────────────────────────────

CREATE OR REPLACE VIEW v_daily_activity AS
SELECT
  date_trunc('day', al.created_at)::date AS day,
  al.action,
  count(*) AS count
FROM activity_log al
GROUP BY 1, 2;
GRANT SELECT ON v_daily_activity TO authenticated;

CREATE OR REPLACE VIEW v_score_distribution AS
SELECT
  rr.job_id,
  width_bucket(rr.overall_score::numeric, 0, 100, 10) AS bucket,
  count(*) AS count
FROM rankora_results rr
WHERE rr.overall_score IS NOT NULL
GROUP BY 1, 2;
GRANT SELECT ON v_score_distribution TO authenticated;

CREATE OR REPLACE VIEW v_stage_conversion AS
SELECT
  sh.job_id,
  sh.from_stage,
  sh.to_stage,
  count(*) AS count
FROM stage_history sh
GROUP BY 1, 2, 3;
GRANT SELECT ON v_stage_conversion TO authenticated;

CREATE OR REPLACE VIEW v_time_to_hire AS
SELECT
  ho.job_id,
  avg(extract(epoch FROM ho.created_at - rj.created_at) / 86400)::numeric(10,1) AS avg_days
FROM hire_outcomes ho
JOIN rankora_jobs rj ON rj.id = ho.job_id
GROUP BY 1;
GRANT SELECT ON v_time_to_hire TO authenticated;

CREATE OR REPLACE VIEW v_top_jobs AS
SELECT
  rj.id AS job_id,
  rj.title,
  count(rr.id) AS resume_count,
  avg(rr.overall_score)::numeric(5,1) AS avg_score,
  rj.created_at
FROM rankora_jobs rj
LEFT JOIN rankora_resumes rr ON rr.job_id = rj.id
GROUP BY rj.id, rj.title, rj.created_at
ORDER BY resume_count DESC;
GRANT SELECT ON v_top_jobs TO authenticated;


-- ────────────────────────────────────────────────────────────────────────────
-- PART 3: Missing RPC functions
-- ────────────────────────────────────────────────────────────────────────────

-- deduct_credits — atomic credit deduction
CREATE OR REPLACE FUNCTION deduct_credits(p_user_id uuid, p_amount int)
RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  v_account_id uuid;
  v_current int;
BEGIN
  v_account_id := get_primary_account(p_user_id);
  IF v_account_id IS NULL THEN RETURN false; END IF;

  SELECT COALESCE((pl.limits_json->>'ai_credits_per_month')::int, 30)
  INTO v_current
  FROM account_app_access aaa
  JOIN plans pl ON pl.id = aaa.plan_id
  WHERE aaa.account_id = v_account_id AND aaa.app_id = get_app_id('rankora');

  -- For now, always allow (credits are plan-based not balance-based in BUBS)
  RETURN true;
END;
$$;
GRANT EXECUTE ON FUNCTION deduct_credits(uuid, int) TO authenticated;

-- has_role — check if user has a specific role
CREATE OR REPLACE FUNCTION has_role(p_user_id uuid, p_role text)
RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER AS $$
  SELECT EXISTS (
    SELECT 1 FROM user_roles WHERE user_id = p_user_id AND role = p_role
  );
$$;
GRANT EXECUTE ON FUNCTION has_role(uuid, text) TO authenticated;

-- is_job_owner — check if user owns the job
CREATE OR REPLACE FUNCTION is_job_owner(p_job_id uuid, p_user_id uuid)
RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER AS $$
  SELECT EXISTS (
    SELECT 1 FROM rankora_jobs rj
    JOIN accounts a ON a.id = rj.account_id
    WHERE rj.id = p_job_id AND a.owner_user_id = p_user_id
  );
$$;
GRANT EXECUTE ON FUNCTION is_job_owner(uuid, uuid) TO authenticated;

-- get_job_form_fields — return custom form fields for a job
CREATE OR REPLACE FUNCTION get_job_form_fields(p_job_id uuid)
RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER AS $$
  SELECT COALESCE(jsonb_agg(row_to_json(f.*) ORDER BY f.sort_order), '[]'::jsonb)
  FROM job_form_fields f WHERE f.job_id = p_job_id;
$$;
GRANT EXECUTE ON FUNCTION get_job_form_fields(uuid) TO anon, authenticated;

-- increment_job_view — track job page views
CREATE OR REPLACE FUNCTION increment_job_view(p_job_id uuid)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  INSERT INTO activity_log (user_id, action, entity_type, entity_id)
  VALUES (COALESCE(auth.uid(), '00000000-0000-0000-0000-000000000000'), 'view_job', 'job', p_job_id);
END;
$$;
GRANT EXECUTE ON FUNCTION increment_job_view(uuid) TO anon, authenticated;

-- is_career_slug_available — check if a career page slug is taken
CREATE OR REPLACE FUNCTION is_career_slug_available(p_slug text)
RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER AS $$
  SELECT NOT EXISTS (
    SELECT 1 FROM rankora_career_pages WHERE slug = p_slug
  );
$$;
GRANT EXECUTE ON FUNCTION is_career_slug_available(text) TO authenticated;

-- user_hit_rate — calculate user's hiring success rate
CREATE OR REPLACE FUNCTION user_hit_rate(p_user_id uuid)
RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER AS $$
  SELECT jsonb_build_object(
    'total_jobs', (SELECT count(*) FROM rankora_jobs rj JOIN accounts a ON a.id = rj.account_id WHERE a.owner_user_id = p_user_id),
    'total_hires', (SELECT count(*) FROM hire_outcomes ho JOIN rankora_jobs rj ON rj.id = ho.job_id JOIN accounts a ON a.id = rj.account_id WHERE a.owner_user_id = p_user_id),
    'avg_time_to_hire_days', (
      SELECT COALESCE(avg(extract(epoch FROM ho.created_at - rj.created_at) / 86400)::numeric(10,1), 0)
      FROM hire_outcomes ho JOIN rankora_jobs rj ON rj.id = ho.job_id JOIN accounts a ON a.id = rj.account_id WHERE a.owner_user_id = p_user_id
    )
  );
$$;
GRANT EXECUTE ON FUNCTION user_hit_rate(uuid) TO authenticated;

-- user_productivity_stats — productivity metrics
CREATE OR REPLACE FUNCTION user_productivity_stats(p_user_id uuid)
RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER AS $$
  SELECT jsonb_build_object(
    'resumes_screened', (SELECT count(*) FROM rankora_results rr JOIN rankora_jobs rj ON rj.id = rr.job_id JOIN accounts a ON a.id = rj.account_id WHERE a.owner_user_id = p_user_id),
    'jobs_completed', (SELECT count(*) FROM rankora_jobs rj JOIN accounts a ON a.id = rj.account_id WHERE a.owner_user_id = p_user_id AND rj.status = 'completed'),
    'avg_score', (SELECT COALESCE(avg(rr.overall_score)::numeric(5,1), 0) FROM rankora_results rr JOIN rankora_jobs rj ON rj.id = rr.job_id JOIN accounts a ON a.id = rj.account_id WHERE a.owner_user_id = p_user_id)
  );
$$;
GRANT EXECUTE ON FUNCTION user_productivity_stats(uuid) TO authenticated;

-- Fix toggle_feature_vote column reference
CREATE OR REPLACE FUNCTION toggle_feature_vote(p_request_id uuid)
RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  v_exists boolean;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM rankora_feature_request_votes
    WHERE request_id = p_request_id AND user_id = auth.uid()
  ) INTO v_exists;

  IF v_exists THEN
    DELETE FROM rankora_feature_request_votes
    WHERE request_id = p_request_id AND user_id = auth.uid();
    UPDATE rankora_feature_requests SET votes = GREATEST(votes - 1, 0) WHERE id = p_request_id;
    RETURN false;
  ELSE
    INSERT INTO rankora_feature_request_votes (request_id, user_id)
    VALUES (p_request_id, auth.uid());
    UPDATE rankora_feature_requests SET votes = votes + 1 WHERE id = p_request_id;
    RETURN true;
  END IF;
END;
$$;
GRANT EXECUTE ON FUNCTION toggle_feature_vote(uuid) TO authenticated;


-- ────────────────────────────────────────────────────────────────────────────
-- PART 4: Grant service_role full access to new tables
-- ────────────────────────────────────────────────────────────────────────────
GRANT ALL ON ALL TABLES IN SCHEMA public TO service_role;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO service_role;
GRANT ALL ON ALL FUNCTIONS IN SCHEMA public TO service_role;

