GRANT SELECT, INSERT, UPDATE, DELETE ON scorecard_templates TO authenticated;

-- scorecard_responses
CREATE TABLE IF NOT EXISTS scorecard_responses (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  template_id uuid REFERENCES scorecard_templates(id) ON DELETE CASCADE,
  resume_id uuid REFERENCES rankora_resumes(id) ON DELETE CASCADE,
  job_id uuid REFERENCES rankora_jobs(id) ON DELETE CASCADE,
  reviewer_id uuid REFERENCES users(id),
  scores jsonb NOT NULL DEFAULT '{}',
  overall_rating int,
  notes text,
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE scorecard_responses ENABLE ROW LEVEL SECURITY;
CREATE POLICY scorecard_responses_all ON scorecard_responses FOR ALL TO authenticated USING (true) WITH CHECK (true);
GRANT SELECT, INSERT, UPDATE, DELETE ON scorecard_responses TO authenticated;

-- job_form_fields (custom fields per job)
CREATE TABLE IF NOT EXISTS job_form_fields (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  job_id uuid NOT NULL REFERENCES rankora_jobs(id) ON DELETE CASCADE,
  field_name text NOT NULL,
  field_type text NOT NULL DEFAULT 'text',
  is_required boolean NOT NULL DEFAULT false,
  options jsonb,
  sort_order int NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE job_form_fields ENABLE ROW LEVEL SECURITY;
CREATE POLICY job_form_fields_all ON job_form_fields FOR ALL TO authenticated USING (true) WITH CHECK (true);
CREATE POLICY job_form_fields_public ON job_form_fields FOR SELECT USING (true);
GRANT SELECT ON job_form_fields TO anon, authenticated;
GRANT INSERT, UPDATE, DELETE ON job_form_fields TO authenticated;

-- stage_automations
CREATE TABLE IF NOT EXISTS stage_automations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  job_id uuid REFERENCES rankora_jobs(id) ON DELETE CASCADE,
  from_stage text,
  to_stage text NOT NULL,
  trigger_type text NOT NULL DEFAULT 'manual',
  action_type text NOT NULL DEFAULT 'move',
  config jsonb DEFAULT '{}',
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE stage_automations ENABLE ROW LEVEL SECURITY;
CREATE POLICY stage_automations_all ON stage_automations FOR ALL TO authenticated USING (true) WITH CHECK (true);
GRANT SELECT, INSERT, UPDATE, DELETE ON stage_automations TO authenticated;

-- stage_history
CREATE TABLE IF NOT EXISTS stage_history (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  resume_id uuid REFERENCES rankora_resumes(id) ON DELETE CASCADE,
  job_id uuid REFERENCES rankora_jobs(id) ON DELETE CASCADE,
  from_stage text,
  to_stage text NOT NULL,
  changed_by uuid REFERENCES users(id),
  changed_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE stage_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY stage_history_all ON stage_history FOR ALL TO authenticated USING (true) WITH CHECK (true);
GRANT SELECT, INSERT ON stage_history TO authenticated;

-- pipeline_stages (compat alias for job_pipeline_stages)
CREATE OR REPLACE VIEW pipeline_stages AS
SELECT * FROM job_pipeline_stages;
GRANT SELECT, INSERT, UPDATE, DELETE ON pipeline_stages TO authenticated;

-- activity_log (user activity tracking)
CREATE TABLE IF NOT EXISTS activity_log (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  account_id uuid REFERENCES accounts(id) ON DELETE CASCADE,
  action text NOT NULL,
  entity_type text,
  entity_id uuid,
  metadata jsonb DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_activity_log_user ON activity_log(user_id, created_at DESC);
ALTER TABLE activity_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY activity_log_select ON activity_log FOR SELECT TO authenticated USING (user_id = auth.uid() OR is_account_member(account_id));
CREATE POLICY activity_log_insert ON activity_log FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid());
GRANT SELECT, INSERT ON activity_log TO authenticated;

-- system_error_logs
CREATE TABLE IF NOT EXISTS system_error_logs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  level text NOT NULL DEFAULT 'error',
  source text,
  message text NOT NULL,
  stack text,
  metadata jsonb DEFAULT '{}',
  user_id uuid REFERENCES users(id),
